SELECT pt.id, pt.pid, pt.phase_id as phaseId, pt.phase_name as phaseName, pt.name, pt.type, pt.plan_start_time as planStartTime, pt.plan_end_time as planEndTime, pt.priority, pt.status, pt.is_fixed as isFixed, pt.charge_name as chargeName, pt.quote_sys_task_id as quoteSysTaskId, pt.product_id as productId, pt.charge_id as chargeId, pt.process_id as processId, pt.role_name as roleName, pt.distribution_type as distributionType, pt.related_sku_type as relatedSkuType, pp.seq FROM project_task pt left join project_phase pp on pt.phase_id = pp.id WHERE pt.product_id = #{params.productId} AND pt.is_deleted = FALSE
AND pt.phase_id = #{params.phaseId}
AND pt.name LIKE concat('%',#{params.searchKeyword},'%')
AND strpos (pt.charge_id,#{userId})>0
AND pt.status IN
#{state}
AND pt.name LIKE concat('%',#{params.taskSearchDTO.searchKeyword},'%')
AND pt.priority in
#{priority}
AND pt.charge_id in
#{chargeId}
AND pt.status in
#{status}
AND pt.create_time >= #{params.taskSearchDTO.startTime}
AND pt.create_time <= #{params.taskSearchDTO.endTime}
ORDER BY
pp.seq ${item.sort}
${item.field} ${item.sort}
pt.create_time asc

