SELECT pt.id, pt.pid, pt.phase_id as phaseId, pt.phase_name as phaseName, pt.name, pt.type, pt.plan_start_time as planStartTime, pt.plan_end_time as planEndTime, pt.priority, pt.status, pt.is_fixed as isFixed, pt.charge_name as chargeName, pt.quote_sys_task_id as quoteSysTaskId, pt.product_id as productId, pt.charge_id as chargeId, pt.process_id as processId, pt.role_name as roleName, pt.distribution_type as distributionType, pt.related_sku_type as relatedSkuType, pt.work_period AS workPeriod FROM project_task pt left join product_info pdi on pt.product_id = pdi.id left join project_info pji on pdi.id = pji.product_id left join (select task_id,source,array_to_string(array_agg(charge_ids),',') as charge_ids from task_charge_distribution group by task_id,source) tcd on pt.id = tcd.task_id and tcd.source = 3 where (pdi.approval_status is null or pdi.approval_status != 4) and (pji.project_status is null or pji.project_status != 4)
AND pt.product_id = #{params.groupFlag}
AND pt.process_id IN
#{processId}
AND pt.plan_end_time >= #{params.startTime}
AND pt.plan_end_time <= #{params.endTime}
AND pt.process_id IN
#{processId}
AND pt.status NOT IN
#{state}
AND pt.name LIKE concat('%',#{params.searchKeyword},'%')
AND (not EXISTS (select a.pre_task_id from pre_task a where a.task_id = pt.id) or not EXISTS (select b.id from pre_task a left join project_task b on a.pre_task_id = b.id where (b.status != 4 and b.status != 5) and a.task_id = pt.id ))
AND EXISTS (select b.id from pre_task a left join project_task b on a.pre_task_id = b.id where b.status in (0,1,2,3,7) and a.task_id = pt.id)
AND pt.name LIKE concat('%',#{params.taskSearchDTO.searchKeyword},'%')
AND pt.priority in
#{priority}
AND pt.charge_id in
#{chargeId}
AND pt.status in
#{status}
AND pt.create_time >= #{params.taskSearchDTO.startTime}
AND pt.create_time <= #{params.taskSearchDTO.endTime}
${params.param}
ORDER BY
${item.field} ${item.sort}
pt.update_time desc

SELECT id,pid,phase_id,phase_name,name,type,plan_start_time,plan_end_time,priority,status,
charge_name,quote_sys_task_id,product_id,charge_id,process_id FROM project_task
WHERE  status!=#{state}
AND plan_end_time >= #{startTime}  AND plan_end_time <= #{endTime}
UNION ALL
SELECT id,pid,phase_id,phase_name,name,type,plan_start_time,plan_end_time,priority,status,
charge_name,quote_sys_task_id,product_id,charge_id,process_id FROM project_task
WHERE   status!=#{state} AND plan_end_time < #{startTime}

select t.* from (select pi.id as productId, pi.name as productName, pi.approval_status, pt.name as taskName, to_char(pt.plan_start_time, 'yyyy-MM-dd') as plan_start_time, to_char(pt.plan_end_time, 'yyyy-MM-dd') as plan_end_time, to_char(pt.reality_start_time, 'yyyy-MM-dd') as reality_start_time, to_char(pt.reality_end_time, 'yyyy-MM-dd') as reality_end_time, pt.id as taskId, pt.status, regexp_split_to_table(pt.charge_id,',') as charge_id, regexp_split_to_table(pt.charge_name,',') as charge_name, pt.phase_name, pi2.project_status, case when pt.plan_end_time is null then 0 when to_char(pt.plan_end_time, 'YYYYMMDD') >= to_char(now(), 'YYYYMMDD') then 0 when to_char(now(), 'YYYYMMDD') > to_char(pt.plan_end_time, 'YYYYMMDD') and pt.status != 4 and pt.status != 5 then 1 else 0 end isDelay from product_info pi inner join project_task pt on pi.id = pt.product_id left join project_info pi2 on pi.id = pi2.product_id where pi.is_finished_product_dev = 1 ) t
and
string_to_array(t.charge_id,',') && string_to_array(#{item}, ',')
and t.productId in
#{item}
and t.status in
#{item}
and t.approval_status in
#{item}
and t.project_status in
#{item}
${dto.param}
order by t.charge_id desc, t.plan_end_time asc, t.taskId desc

select t.* from (select pi.id as productId, pi.name as productName, pi.approval_status, pi.create_time, pt.name as taskName, to_char(pt.plan_start_time, 'yyyy-MM-dd') as plan_start_time, to_char(pt.plan_end_time, 'yyyy-MM-dd') as plan_end_time, to_char(pt.reality_start_time, 'yyyy-MM-dd') as reality_start_time, to_char(pt.reality_end_time, 'yyyy-MM-dd') as reality_end_time, pt.id as taskId, pt.status, pt.charge_id as charge_id, pt.charge_name as charge_name, pi2.project_status, case when pt.plan_end_time is null then 0 when to_char(pt.plan_end_time, 'YYYYMMDD') >= to_char(now(), 'YYYYMMDD') then 0 when to_char(now(), 'YYYYMMDD') > to_char(pt.plan_end_time, 'YYYYMMDD') and pt.status != 4 and pt.status != 5 then 1 else 0 end isDelay from product_info pi inner join project_task pt on pi.id = pt.product_id left join project_info pi2 on pi.id = pi2.product_id where pi.is_finished_product_dev = 1 ) t
and
string_to_array(t.charge_id,',') && string_to_array(#{item}, ',')
and t.productId in
#{item}
and t.status in
#{item}
and t.approval_status in
#{item}
and t.project_status in
#{item}
${dto.param}
order by t.create_time desc,t.productId asc, t.plan_end_time asc, t.taskId desc

select t.* from (select pi.id as productId, pi.name as productName, pi.approval_status, pt.name as taskName, to_char(pt.plan_start_time, 'yyyy-MM-dd') as plan_start_time, to_char(pt.plan_end_time, 'yyyy-MM-dd') as plan_end_time, to_char(pt.reality_start_time, 'yyyy-MM-dd') as reality_start_time, to_char(pt.reality_end_time, 'yyyy-MM-dd') as reality_end_time, pt.id as taskId, pt.status, pt.charge_id as charge_id, pt.charge_name as charge_name, pt.phase_id, pt.phase_name, pi2.project_status, case when pt.plan_end_time is null then 0 when to_char(pt.plan_end_time, 'YYYYMMDD') >= to_char(now(), 'YYYYMMDD') then 0 when to_char(now(), 'YYYYMMDD') > to_char(pt.plan_end_time, 'YYYYMMDD') and pt.status != 4 and pt.status != 5 then 1 else 0 end isDelay, pp.create_time from product_info pi inner join project_task pt on pi.id = pt.product_id left join project_info pi2 on pi.id = pi2.product_id left join project_phase pp on pt.phase_id = pp.id where pi.is_finished_product_dev = 1 ) t
and
string_to_array(t.charge_id,',') && string_to_array(#{item}, ',')
and t.productId in
#{item}
and t.status in
#{item}
and t.approval_status in
#{item}
and t.project_status in
#{item}
${dto.param}
order by t.create_time desc, t.phase_name asc, t.plan_end_time asc, t.taskId desc

select t.* from (select pi.id as productId, pi.name as productName, pi.charge_id, pi.charge_name, pi.approval_status, pi2.project_status, pd.id as skuId, pd.sku_no, to_char(pd.plan_listing_time, 'yyyy-MM-dd') as plan_listing_time, COALESCE(to_char(pd.plan_listing_time, 'YYYYMM'),'') as timeInterval, COALESCE(pi2.project_status,pi.approval_status) as status, case when COALESCE(pi2.project_status,-1) = -1 then 0 else 1 end as isProjectStatus from product_info pi inner join product_detail pd on pi.id = pd.product_id left join project_info pi2 on pi.id = pi2.product_id where pi.is_finished_product_dev = 1 ) t
and
string_to_array(t.charge_id,',') && string_to_array(#{item}, ',')
and t.productId in
#{item}
and t.approval_status in
#{item}
and t.project_status in
#{item}
${dto.param}
order by t.plan_listing_time asc nulls last, t.skuId desc

SELECT pt.id AS taskId, pt.project_id AS projectId, pi.name AS productName, pt.pid, pt.product_id AS productId, pt.name AS taskName, pt.type, pt.charge_id AS chargeId, pt.charge_name AS chargeName, to_char(pt.plan_start_time, 'yyyy-MM-dd') as planStartTime, to_char(pt.plan_end_time, 'yyyy-MM-dd') as planEndTime, to_char(pt.reality_start_time, 'yyyy-MM-dd') as realityStartTime, to_char(pt.reality_end_time, 'yyyy-MM-dd') as realityEndTime, pt.priority, pt.phase_id AS phaseId, pt.phase_name AS phaseName, pt.description, pt.is_milepost AS isMilepost, pt.create_user_name AS createUserName, pt.create_time AS createTime, pt.update_time AS updateTime, pt.update_user_name AS updateUserName, pt.schedule_status AS scheduleStatus, pt.schedule_type AS scheduleType, pt.status, pt.work_period as workPeriod, COALESCE((SELECT seq FROM project_phase WHERE id=pt.phase_id LIMIT 1),0) AS phaseSeq FROM project_task pt LEFT JOIN product_info pi ON pt.product_id=pi.id WHERE pt.product_id=#{dto.productId}
AND pt.phase_name='立项阶段'
AND pt.phase_name!='立项阶段'
AND string_to_array(pt.charge_id,',') && string_to_array(#{dto.taskChargeId},',')
AND pt.name LIKE concat('%',#{dto.searchKeyword},'%')
AND pt.plan_start_time >= #{dto.planStartTime}
AND pt.plan_end_time <= #{dto.planEndTime}
AND pt.schedule_status = #{dto.planAuditState}
AND pt.id IN
#{taskId}
${dto.param}
ORDER BY
${item.field} ${item.sort}
pt.create_time asc

SELECT COUNT(*) AS "taskCount",
(SELECT name AS "productName"  FROM product_info WHERE id=#{productId})
FROM project_task WHERE product_id=#{productId}

SELECT product_id, id AS taskid, plan_start_time, plan_end_time, charge_id, charge_name, schedule_status, pid, schedule_type FROM project_task WHERE product_id=#{productId}
AND id IN
#{taskId}

SELECT pt.product_id, pt.name AS taskName, pi.name AS productName, pt.id AS taskid, pt.plan_start_time, pt.plan_end_time, pt.charge_name, pt.schedule_status FROM project_task pt LEFT JOIN product_info pi ON pt.product_id=pi.id WHERE product_id=#{dto.productId}
AND pt.id IN
#{taskId}

SELECT pt.id AS taskId, pt.name AS taskName, to_char(pt.plan_start_time, 'yyyy-MM-dd') AS originStartTime, to_char(pt.plan_end_time,'yyyy-MM-dd') AS originEndTime, pt.charge_name, pt.status FROM project_task pt WHERE pt.product_id=#{dto.productId}
AND pt.id IN
#{taskId}

